package dev.koikaster.mite;
import com.mojang.blaze3d.shaders.FogShape;import net.minecraft.client.*;import net.minecraft.client.multiplayer.ClientLevel;import net.minecraft.client.renderer.FogRenderer;import net.minecraft.core.particles.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.util.Mth;import net.minecraft.world.effect.MobEffects;import net.minecraft.world.item.*;import net.minecraft.world.level.Level;import net.minecraft.world.level.material.FogType;import net.minecraftforge.api.distmarker.Dist;import net.minecraftforge.client.event.ViewportEvent;import net.minecraftforge.event.TickEvent;import net.minecraftforge.event.level.LevelEvent;import net.minecraftforge.eventbus.api.*;import net.minecraftforge.fml.common.Mod;
@Mod.EventBusSubscriber(modid=MiteReforged.ID,value=Dist.CLIENT)
public final class ClientLocalWeather1981 {
 private static ClientLevel tracked;private static ResourceLocation dimension;private static int kind;private static float target,amount;
 public static void receive(LocalWeatherTransport1981.Snapshot value){var m=Minecraft.getInstance();if(m.level!=null&&m.level.dimension().location().equals(value.dimension()))apply(m.level,value);}
 private static void apply(ClientLevel level,LocalWeatherTransport1981.Snapshot value){if(tracked!=level){tracked=level;kind=0;amount=0;}dimension=value.dimension();if(value.kind()!=0&&value.kind()!=kind){kind=value.kind();amount=0;}target=value.kind()==0?0:value.strength();}
 private static void clear(){tracked=null;dimension=null;kind=0;target=amount=0;}
 @SubscribeEvent public static void tick(TickEvent.ClientTickEvent event){if(event.phase!=TickEvent.Phase.END)return;var m=Minecraft.getInstance();if(m.level==null||m.player==null){clear();return;}if(tracked!=m.level){tracked=m.level;kind=0;target=amount=0;dimension=m.level.dimension().location();}amount=Mth.lerp(.08f,amount,target);if(amount<.002f&&target==0){amount=0;kind=0;}if(!viewer(m)||amount<.08f||kind==LocalWeather1981.Kind.MOUNTAIN_FOG.ordinal())return;int count=Math.min(5,1+(int)(amount*4));for(int i=0;i<count;i++){double x=m.player.getX()+(m.level.random.nextDouble()-.5)*16,y=m.player.getEyeY()+m.level.random.nextDouble()*5-1,z=m.player.getZ()+(m.level.random.nextDouble()-.5)*16;if(!LocalWeather1981.exposed(m.level,net.minecraft.core.BlockPos.containing(x,y,z)))continue;if(kind==LocalWeather1981.Kind.SANDSTORM.ordinal())m.level.addParticle(new DustParticleOptions(new org.joml.Vector3f(.58f,.44f,.25f),.8f),x,y,z,.12,-.01,-.04);else if(kind==LocalWeather1981.Kind.BLIZZARD.ordinal())m.level.addParticle(new ItemParticleOption(ParticleTypes.ITEM,new ItemStack(Items.SNOWBALL)),x,y,z,.12,-.025,-.04);}}
 private static boolean viewer(Minecraft m){return m.level!=null&&m.player!=null&&m.level==tracked&&m.level.dimension()==Level.OVERWORLD&&dimension!=null&&dimension.equals(m.level.dimension().location())&&!m.player.isSpectator()&&!m.player.hasEffect(MobEffects.BLINDNESS)&&!m.player.hasEffect(MobEffects.DARKNESS)&&m.gameRenderer.getMainCamera().getFluidInCamera()==FogType.NONE;}
 @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true)public static void fog(ViewportEvent.RenderFog event){var m=Minecraft.getInstance();if(!viewer(m)||amount<=.001f||event.getCamera().getEntity()!=m.player||event.getType()!=FogType.NONE||event.getMode()!=FogRenderer.FogMode.FOG_TERRAIN)return;float oldFar=event.getFarPlaneDistance(),oldNear=event.getNearPlaneDistance();if(!Float.isFinite(oldFar)||oldFar<=0)return;float cap=kind==LocalWeather1981.Kind.SANDSTORM.ordinal()?24:kind==LocalWeather1981.Kind.BLIZZARD.ordinal()?28:40;float far=Mth.lerp(amount,oldFar,Math.min(oldFar,cap)),near=Mth.lerp(amount,oldNear,Math.min(oldNear,cap*.1f));event.setFarPlaneDistance(far);event.setNearPlaneDistance(Math.max(0,Math.min(near,far)));event.setFogShape(FogShape.SPHERE);event.setCanceled(true);}
 @SubscribeEvent(priority=EventPriority.LOWEST)public static void color(ViewportEvent.ComputeFogColor event){var m=Minecraft.getInstance();if(!viewer(m)||amount<=.001f||event.getCamera().getEntity()!=m.player)return;float brightness=Math.max(event.getRed(),Math.max(event.getGreen(),event.getBlue())),mix=amount*.55f;float r=kind==1?.72f:kind==3?.86f:.78f,g=kind==1?.61f:kind==3?.9f:.82f,b=kind==1?.42f:kind==3?.96f:.84f;event.setRed(Mth.lerp(mix,event.getRed(),brightness*r));event.setGreen(Mth.lerp(mix,event.getGreen(),brightness*g));event.setBlue(Mth.lerp(mix,event.getBlue(),brightness*b));}
 @SubscribeEvent public static void unload(LevelEvent.Unload event){if(event.getLevel()==tracked)clear();}
 private ClientLocalWeather1981(){}
}
